package com.example.starter.consent.ledger;

import java.util.List;
import java.util.Optional;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * 账本域幂等请求持久化访问：复用 idempotency_request 表，操作类型为
 * QUOTA_ADJUST / RESTRICTED_QUERY / QUOTA_CLEAR。成功快照与业务变更同事务写入，失败不占键。
 */
@Repository
public class LedgerIdempotencyRepository {

    private static final RowMapper<Row> MAPPER = (rs, rowNum) -> new Row(
            rs.getString("request_id"),
            rs.getString("operation"),
            rs.getString("params_fingerprint"),
            rs.getString("response_body"));

    private final JdbcTemplate jdbc;

    public LedgerIdempotencyRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 幂等请求行。
     *
     * @param requestId         幂等请求标识
     * @param operation         操作类型
     * @param paramsFingerprint 规范化参数指纹
     * @param responseBody      首次完整成功响应快照（JSON）
     */
    public record Row(String requestId, String operation, String paramsFingerprint, String responseBody) {
    }

    Optional<Row> find(String requestId) {
        List<Row> rows = jdbc.query(
                "SELECT request_id, operation, params_fingerprint, response_body"
                        + " FROM idempotency_request WHERE request_id = ?",
                MAPPER, requestId);
        return rows.stream().findFirst();
    }

    /**
     * 写入幂等行；并发同 requestId 冲突由调用方按唯一约束异常处理。
     */
    void insert(String requestId, String operation, String paramsFingerprint, String responseBody) {
        try {
            jdbc.update(
                    "INSERT INTO idempotency_request (request_id, operation, params_fingerprint, response_body)"
                            + " VALUES (?, ?, ?, ?)",
                    requestId, operation, paramsFingerprint, responseBody);
        } catch (DuplicateKeyException e) {
            throw e;
        }
    }
}

